INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 34, 'theory', 'Quiz: bundlers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 0, 'Why does tree shaking work well with ES modules?', '["They are smaller in size", "Imports and exports are static: they show which names are used", "They are always minified", "CommonJS is forbidden in bundlers"]', 1, 'The static structure of import/export lets you find unused exports without running the code. require() is dynamic.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 1, 'What does the dynamic import(''./editor.js'') do?', '["Includes the module synchronously", "Creates a separate chunk and returns a promise — the module loads on demand", "Removes the module from the bundle", "Works only in Node"]', 1, 'The bundler moves the module and its dependencies into a separate file, which is loaded on the first call.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 2, 'Why is a content hash (contenthash) added to the file name?', '["To protect against copying", "So it can be cached for a long time: the code changed — the name changed", "To make the file smaller", "To sort files"]', 1, 'A file with a hash in its name never changes — it is cached for a year; a new version gets a new name.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 3, 'What is a source map for?', '["To speed up loading", "It maps positions in the minified code to the original ones: debugging shows your files and lines", "To compress images", "For a site map"]', 1, 'A source map is a file with VLQ-encoded "generated position → original position" mappings. DevTools reads it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 34, 4, 'What does "sideEffects": false in package.json mean?', '["The package has no bugs", "The package''s modules have no side effects on load: unused ones can be safely removed", "The package can''t be published", "Imports are forbidden"]', 1, 'The bundler confidently drops imports with no used names from such packages; files with effects (for example CSS) are listed in an array.');
